import{_ as a,o as i,c as n,a2 as s}from"./chunks/framework.CDpkVv68.js";const u=JSON.parse('{"title":"Mining","description":"","frontmatter":{},"headers":[],"relativePath":"es/guide/professions/mining.md","filePath":"es/guide/professions/mining.md"}'),r={name:"es/guide/professions/mining.md"};function o(t,e,c,l,d,p){return i(),n("div",null,[...e[0]||(e[0]=[s('<h1 id="mining" tabindex="-1">Mining <a class="header-anchor" href="#mining" aria-label="Enlace permanente a &quot;Mining&quot;">​</a></h1><p><strong>Estado del diseño: Propuesto.</strong> Esta página describe el rediseño previsto, no mecánicas confirmadas en el juego. <strong>Implementación/disponibilidad:</strong> no establecida para este rediseño. <strong>Verificación:</strong> solo revisión documental. <strong>Revisado:</strong> 2026-10-08 frente a la <a href="/Syrolands-Public/es/game-design/professions/mining.html">especificación completa del diseño</a>.</p><h2 id="tl-dr" tabindex="-1">TL;DR <a class="header-anchor" href="#tl-dr" aria-label="Enlace permanente a &quot;TL;DR&quot;">​</a></h2><ul><li>Mining combina conocimiento geológico, prospección y extracción.</li><li>Algunos depósitos seleccionados pueden abrir pasajes diseñados; no permite excavar sin restricciones.</li><li>Importan la procedencia del material y los riesgos estructurales; los derrumbes y permisos siguen sin resolverse.</li></ul><h2 id="what-it-does" tabindex="-1">Qué hace <a class="header-anchor" href="#what-it-does" aria-label="Enlace permanente a &quot;Qué hace&quot;">​</a></h2><p>Mining combina prospección, conocimiento geológico y extracción. Interpretar rocas, vetas y terreno debería ayudar a evaluar qué hay y cuánto promete. La composición regional y la procedencia pueden dar un carácter distinto a los materiales.</p><h2 id="why-take-it-into-the-field" tabindex="-1">¿Por qué llevarlo a una expedición? <a class="header-anchor" href="#why-take-it-into-the-field" aria-label="Enlace permanente a &quot;¿Por qué llevarlo a una expedición?&quot;">​</a></h2><p>La extracción repetida podría agotar determinadas formaciones rocosas y abrir espacios transitables. Esto sigue la dirección existente de un mundo diseñado, sin permitir excavar libremente en cualquier lugar. Un conocimiento avanzado de la estabilidad podría ayudar en excavaciones peligrosas; derrumbes, recuperación y permisos siguen sin resolverse.</p><h2 id="learning-and-specialization" tabindex="-1">Aprendizaje y especialización <a class="header-anchor" href="#learning-and-specialization" aria-label="Enlace permanente a &quot;Aprendizaje y especialización&quot;">​</a></h2><p>Un Geological Journal registra rocas, minerales, características de las vetas, regiones y observaciones. Prospección, extracción eficiente y comprensión estructural ofrecen distintas formas de aportar valor. Las mejores decisiones deberían mejorar rendimiento o calidad, además de la cantidad de clics.</p><h2 id="progression-and-related-crafts" tabindex="-1">Progresión y oficios relacionados <a class="header-anchor" href="#progression-and-related-crafts" aria-label="Enlace permanente a &quot;Progresión y oficios relacionados&quot;">​</a></h2><p>Se utiliza el <a href="/Syrolands-Public/es/guide/professions/overview.html">aprendizaje compartido de profesiones</a>, con trabajo útil desde el inicio y conocimiento más profundo con el tiempo. Mining indica qué contiene un depósito; <a href="/Syrolands-Public/es/guide/professions/blacksmithing.html">Blacksmithing</a> indica para qué sirve ese material. Los soportes de <a href="/Syrolands-Public/es/guide/professions/carpentry.html">Carpentry</a> y mecanismos de <a href="/Syrolands-Public/es/guide/professions/tinkering.html">Tinkering</a> se proponen como colaboraciones avanzadas.</p><p><a href="/Syrolands-Public/es/guide/professions/overview.html">Todas las profesiones</a> · <a href="/Syrolands-Public/es/game-design/professions/mining.html">Especificación completa del diseño</a></p>',13)])])}const g=a(r,[["render",o]]);export{u as __pageData,g as default};
